test_that("Wrapper code is up-to-date", {
  # This helper function removes all empty lines and all # nolint statements
  # from wrappers, which may differ
  clean_wrappers <- function(lines) {
    lines <- stringi::stri_trim(lines)
    lines <- lines[nzchar(lines)]
    idx <- stringi::stri_detect_regex(lines, "#\\s*nolint", negate = TRUE)
    lines <- lines[idx]
    # Strip static file header added by the document binary
    idx <- stringi::stri_detect_regex(
      lines,
      "^# Generated by extendr|^#' @usage NULL$|^#' @useDynLib|^NULL$",
      negate = TRUE
    )
    lines[idx]
  }

  # What we're doing here is generating the latest wrappers for the
  # Rust library and comparing to the wrappers file stored in the
  # package R code. There are two reasons why this test may fail:
  # 1. The wrapper code needs updating via `make_wrappers()`.
  # 2. The Rust code that generates the wrappers has a problem.
  #
  # Make sure you know which it is before running `make_wrappers()`.

  x <- .Call(
    "wrap__make_extendrtests_wrappers",
    use_symbols = TRUE,
    package_name = "extendrtests"
  )
  x <- strsplit(x, "\n")[[1]]

  # locating the file containing the R wrappers is a bit complicated,
  # because it depends on whether testthat is run locally or as part
  # of R CMD check.

  tmp <- file.path("..", "..", "R", "extendr-wrappers.R")
  if (file.exists(tmp)) {
    # testthat run locally?
    source <- tmp
  } else {
    # testthat run as part of R CMD check?
    tmp <- file.path(
      "..",
      "..",
      "00_pkg_src",
      "extendrtests",
      "R",
      "extendr-wrappers.R"
    )
    if (file.exists(tmp)) {
      source <- tmp
    } else {
      skip("Cannot locate wrapper code.")
    }
  }

  y <- brio::read_lines(source)
  expect_equal(clean_wrappers(x), clean_wrappers(y))
})

test_that("Rust function prefixed with `_` can be called", {
  expect_visible(`__00__special_function_name`())
})

test_that("Rust classes and methods prefixed with `_` can be invoked", {
  x <- `__MyClass`$new()
  expect_visible(x$`__name_test`())
})

test_that("Rust `_arg` is correctly wrapped in R", {
  x <- 100L
  y <- 42L
  expect_equal(special_param_names(`_y` = y, `_x` = x), x - y)
})

test_that("Renamed functions work correctly", {
  expect_equal(test.rename.rlike(), 1)
  expect_equal(.Call(wrap__test_rename_mymod), 1)
})

test_that("Call to Rust via wrapper functions works", {
  expect_equal(hello_world(), "Hello world!")
  expect_visible(hello_world())

  expect_equal(do_nothing(), NULL)
  expect_visible(do_nothing())
  expect_equal(check_default(), TRUE)
  expect_equal(check_default("xyz"), FALSE)
})

test_that("Option arguments default to NULL", {
  expect_true(check_option_default_int())
  expect_false(check_option_default_int(1L))
  expect_true(check_option_default_int(NULL))

  expect_true(check_option_default_str())
  expect_false(check_option_default_str("a"))

  expect_true(check_option_default_vec())
  expect_false(check_option_default_vec(c("a", "b")))

  expect_equal(check_option_strings(), -1L)
  expect_equal(check_option_strings(c("a", "b")), 2L)
  expect_equal(check_option_strings(NA_character_), 1L)
  expect_error(check_option_strings(1), "failed to convert argument `x`")

  expect_equal(check_option_integers(), -1L)
  expect_equal(check_option_integers(c(1L, NA)), 2L)
  expect_error(check_option_integers("a"), "failed to convert argument `x`")

  expect_equal(check_option_doubles(), -1L)
  expect_equal(check_option_doubles(c(1, NA)), 2L)

  expect_equal(check_option_logicals(), -1L)
  expect_equal(check_option_logicals(c(TRUE, NA)), 2L)

  expect_equal(check_option_complexes(), -1L)
  expect_equal(check_option_complexes(c(1i, 2i)), 2L)

  expect_equal(check_option_raw(), -1L)
  expect_equal(check_option_raw(as.raw(1:2)), 2L)

  expect_equal(check_option_list(), -1L)
  expect_equal(check_option_list(list(1, "a")), 2L)
  expect_error(check_option_list(1), "failed to convert argument `x`")

  expect_equal(check_option_pairlist(), -1L)
  expect_equal(check_option_pairlist(pairlist(a = 1, b = 2)), 2L)

  expect_equal(check_option_expressions(), -1L)
  expect_equal(check_option_expressions(expression(a, b)), 2L)

  expect_equal(check_option_language(), -1L)
  expect_equal(check_option_language(quote(f(x))), 2L)

  expect_true(check_option_symbol())
  expect_false(check_option_symbol(quote(a)))

  expect_true(check_option_function())
  expect_false(check_option_function(function() 1))

  expect_true(check_option_environment())
  expect_false(check_option_environment(new.env()))

  expect_equal(check_option_default_after_required(1L), 1L)
  expect_equal(check_option_default_after_required(1L, 2L), 3L)
  expect_error(check_option_default_after_required())

  expect_false(check_option_default_override())
  expect_true(check_option_default_override(NULL))
  expect_equal(formals(check_option_default_override), as.pairlist(alist(x = 1L)))

  expect_equal(formals(check_option_default_int), as.pairlist(alist(x = NULL)))
})

test_that("Default parameter values are emitted to wrappers", {
  expect_equal(get_default_value(), 42L)
  expect_equal(MyClass$get_default_value(), 42L)
})

test_that("Function with invisible flag returns invisibly", {
  expect_equal(invisible_string(), "This should be invisible")
  expect_invisible(invisible_string())
})

test_that("Nullable wrapper processes not null value", {
  expect_equal(add_5_if_not_null(5L), 10L)
})

test_that("Nullable wrapper propagates NULL", {
  expect_null(add_5_if_not_null(NULL))
})
